async function hydrateRisk(target:Address,version:number,current:Snapshot){
 let timer:ReturnType<typeof setTimeout>|undefined;
 try{const risk=await Promise.race([readLoanRisk(client,config,target,current.block),new Promise<never>((_,reject)=>{timer=setTimeout(()=>reject(Error('Loan risk read timed out.')),20000);})]);if(version!==loadVersion||data!==current)return;current.risk=risk;}
 catch{if(version===loadVersion&&data===current)current.riskError=true;}
 finally{clearTimeout(timer);if(version===loadVersion&&data===current){current.riskLoading=false;renderSupplemental();}}
}
async function hydrateInvoices(target:Address,version:number,current:Snapshot,start:number,end:number){
 const active=()=>version===loadVersion&&data===current;
 try{
  const ids:Hex[]=checkoutId&&/^0x[0-9a-fA-F]{64}$/.test(checkoutId)?[checkoutId]:await Promise.all(Array.from({length:end-start},(_,i)=>read(target,'invoiceIds',[BigInt(start+i)],current.block)));
  const items:Invoice[]=await Promise.all(ids.reverse().map(async id=>{const i=await read(target,'invoices',[id],current.block);return {id,label:i[0],amount:i[1],expiresAt:i[2],payer:i[3],paid:i[4],canceled:i[5]};}));
  if(!active())return;current.invoices=items.filter(i=>i.amount>0n);
  for(const record of current.records){const invoice=items.find(i=>i.id===record.invoiceId);if(invoice)record.label=invoice.label;}
 }catch{if(active())current.invoiceError=true;}finally{if(active()){current.invoiceLoading=false;renderSupplemental();}}
}
async function hydrateHistory(target:Address,version:number,current:Snapshot,toBlock:bigint){
 const active=()=>version===loadVersion&&data===current;
 try{const result=await historyPage(client,{address:target,events:businessAbi.filter(x=>x.type==='event') as any,deploymentBlock:BigInt(config.deploymentBlock??0),toBlock});if(!active())return;current.records=eventRecords(result.logs,current.invoices);current.historyBefore=result.before;}
 catch{if(active())current.historyError=true;}finally{if(active()){current.historyLoading=false;renderSupplemental();}}
}
function eventRecords(logs:any[],items:Invoice[]):RecordItem[]{return logs.flatMap<RecordItem>(log=>{const a=log.args;const base={hash:log.transactionHash,block:log.blockNumber};switch(log.eventName){case 'ReceiptCollected':return [{...base,kind:'receipt' as const,invoiceId:a.id,amount:a.amount,label:items.find(i=>i.id===a.id)?.label||'Customer receipt'}];case 'RepaymentSettled':return [{...base,kind:'repayment' as const,amount:a.amount,label:'Receipt allocation applied'}];case 'ServiceFeePaid':return [{...base,kind:'fee' as const,amount:a.fee,label:'Tillward service fee paid'}];case 'LoanClosed':return [{...base,kind:'repayment' as const,amount:a.repaid,label:'Loan closed'}];default:return [];}});}
async function olderHistory(toBlock?:bigint){
 if(!data||!account||(toBlock===undefined&&data.historyBefore===undefined)||data.historyLoading||historyBusy)return;
 const current=data,target=account,version=loadVersion;historyBusy=true;render();
 try{const result=await historyPage(client,{address:target,events:businessAbi.filter(x=>x.type==='event') as any,deploymentBlock:BigInt(config.deploymentBlock??0),toBlock:toBlock??current.historyBefore!-1n});if(version!==loadVersion||data!==current)return;const known=new Set(current.records.map(r=>`${r.hash}:${r.kind}`));current.records.push(...eventRecords(result.logs,current.invoices).filter(r=>!known.has(`${r.hash}:${r.kind}`)));current.records.sort((a,b)=>a.block===b.block?0:(a.block??0n)>(b.block??0n)?-1:1);current.historyBefore=result.before;}catch(e){error='Older activity could not be loaded. '+message(e);}finally{historyBusy=false;render();}
}
async function send(functionName:string,args:unknown[]=[],value?:bigint,address=account,abi:any=businessAbi){
 if(busy)return;if(pendingHash){toast('A transaction is still awaiting reconciliation. Refresh before sending another.');return;}busy=true;error='';transactionNotice='';transactionPhase='Preparing your transaction';render();toast('Preparing your transaction.');try{if(!window.ethereum||!wallet||!address)throw new Error('Connect the correct wallet first.');if(address===config.factory?!factoryVerified:!verified)throw new Error('The deployment has not been verified. Refresh to retry.');
 const accounts=await window.ethereum.request({method:'eth_accounts'}) as Address[];if(accounts[0]?.toLowerCase()!==wallet.toLowerCase())throw new Error('Wallet account changed. Reconnect before sending.');
 const chainId=await window.ethereum.request({method:'eth_chainId'});if(Number(chainId)!==config.chainId){try{await window.ethereum.request({method:'wallet_switchEthereumChain',params:[{chainId:'0x'+config.chainId.toString(16)}]});}catch{throw new Error(`Switch your wallet to ${config.network} (chain ${config.chainId}), then retry.`);}}
 if(functionName==='settle'||functionName==='settleDirect'||functionName==='openLoan'||functionName==='addCollateral'){
  const kind=(functionName==='settle'||functionName==='settleDirect')?'repay':functionName==='openLoan'?'open':'add';
  const hints=await insertionHints(client,config,address,kind,kind==='add'?0n:args[0] as bigint,value??0n);
  args=kind==='add'?hints:[args[0],...hints];
 }
 const currentHead=await client.getBlock({blockTag:'latest'});if(!snapshotFreshness(currentHead.timestamp).fresh||currentHead.number<BigInt(config.lastVerifiedBlock??0))throw Error('RPC state is stale. Refresh before signing.');
 if([2,3].includes(config.accountVersion??1)&&functionName==='settle'){const fee=await readServiceState(client,config,address,currentHead.number,args[0] as bigint);if(!fee?.funded)throw Error('Hosted repayment is disabled or retained receipt fee funding is unavailable.');}
 if(functionName==='claimSurplus'){const risk=await readLoanRisk(client,config,account!,currentHead.number);if(!snapshotFreshness(risk.timestamp).fresh||risk.surplus===0n)throw Error('No current claimable collateral surplus is recorded for this business.');}
 const simulation=await client.simulateContract({address,abi,functionName,args,account:wallet,value} as any);
 const estimate=await client.estimateContractGas(simulation.request as any);
 const floor=functionName==='createAccount'?3500000n:functionName==='openLoan'?1600000n:400000n;
 const gas=estimate*12n/10n>floor?estimate*12n/10n:floor;
 const nonce=await client.getTransactionCount({address:wallet,blockTag:'pending'});
 const startBlock=await client.getBlockNumber({cacheTime:0});
 // Persist the exact intent before opening the wallet. A reload or ambiguous
 // provider error must not turn an uncertain send into a duplicate payment.
 savePending({hash:('0x'+'00'.repeat(32)),sender:wallet,nonce,startBlock:String(startBlock),to:address,input:encodeFunctionData({abi,functionName,args} as any),value:String(value??0n),action:functionName});
 transactionPhase='Confirm in your wallet';render();
 const wc=createWalletClient({chain:client.chain,transport:custom(window.ethereum)});
 try{const hash=await wc.writeContract({...simulation.request,gas,nonce,chain:client.chain} as any);savePending({...pendingJournal,hash});transactionPhase='Waiting for network confirmation';}catch(e:any){if(isUserRejection(e))clearPending();throw e;}render();
 const receipt=await client.waitForTransactionReceipt({hash:pendingHash!,confirmations:1,timeout:120000});
 const result=await reconcileTransaction(client,pendingJournal);if(!result.receipt)throw Error('Transaction is still unresolved. Refresh to reconcile.');rememberBlock(receipt.blockNumber);clearPending();if(result.outcome!=='confirmed')throw Error(result.outcome==='reverted'?'Transaction reverted. No success recorded.':'A replacement or cancellation confirmed. Review your workspace before retrying.');if(functionName==='setPolicy')try{localStorage.setItem(`paydown.policy.${config.chainId}.${account}`,'1');}catch{}transactionPhase='';await load();toast('Transaction confirmed. Workspace refreshed from chain.');
 }catch(e){error=message(e);render();}finally{busy=false;transactionPhase='';render();}}
async function createAccount(){if(!config.factory||!wallet)return;await send('createAccount',[],undefined,config.factory,factoryAbi);}
async function pay(){if(!data||!account||!checkoutId||!wallet)return;const i=data.invoices.find(x=>x.id===checkoutId);if(!i)return;try{const allowance=await client.readContract({address:config.musd,abi:tokenAbi,functionName:'allowance',args:[wallet,account]});if(allowance<i.amount){if(allowance>0n){await send('approve',[account,0n],undefined,config.musd,tokenAbi);if(error)return;}await send('approve',[account,i.amount],undefined,config.musd,tokenAbi);if(error)return;}await send('payInvoice',[checkoutId]);}catch(e){error=message(e);render();}}
async function init(){
 try{
  const response=await fetch(local?'/local-deployment.json':'/deployment.json',{cache:'no-store',signal:AbortSignal.timeout(15000)});
  if(!response.ok)throw new Error('Deployment configuration unavailable.');
  config=await response.json();
  deploymentCatalog=[config,...(config.legacyDeployments??[])];
  if(config.chainId!==(local?31337:31611))throw new Error('Unsupported deployment network.');
  const httpTransport=http(config.rpc,{retryCount:1,timeout:15000,fetchOptions:{cache:'no-store'}});
  const transport=config.ws?fallback([webSocket(config.ws,{timeout:15000,retryCount:1}),httpTransport]):httpTransport;
  client=createPublicClient({chain:defineChain({id:config.chainId,name:config.network,nativeCurrency:{name:'Bitcoin',symbol:'BTC',decimals:18},rpcUrls:{default:{http:[config.rpc]}}}),transport});
  const savedAnchor=localStorage.getItem(anchorKey());if(savedAnchor&&/^\d+$/.test(savedAnchor)&&Number.isSafeInteger(Number(savedAnchor)))config.lastVerifiedBlock=Math.max(config.lastVerifiedBlock??0,Number(savedAnchor));
  const saved=localStorage.getItem(`paydown.pending.${config.chainId}`);
  if(saved){pendingJournal=parseJournal(saved);pendingHash=pendingJournal.hash as Hex;}
  if(window.ethereum&&sessionStorage.getItem('tillward.live')==='1'){const accounts=await window.ethereum.request({method:'eth_accounts'}) as Address[];if(accounts[0]&&isAddress(accounts[0])){wallet=accounts[0];mode='live';}}
  render();if(mode==='live')await load();
  setInterval(()=>{if(mode==='live'&&pendingHash&&!busy&&!loading)void load();},15000);
  window.ethereum?.on?.('accountsChanged',()=>{wallet=undefined;data=undefined;account=undefined;verified=false;invoicePage=0;loadVersion++;loading=false;render();});
  window.ethereum?.on?.('chainChanged',()=>{verified=false;void load();});
 }catch(e){$('#app').innerHTML=`<main class="boot-error"><h1>Workspace unavailable</h1><p>${esc(message(e))}</p><button onclick="location.reload()">Reload</button></main>`;}
}
